import { useCallback, useEffect, useRef, useState } from 'react'
import { useNotify, useTranslate } from 'react-admin'
import {
  FormControl,
  FormControlLabel,
  LinearProgress,
  Switch,
} from '@material-ui/core'
import { useInterval } from '../common'
import config from '../config'
import { baseUrl, openInNewTab } from '../utils'
import { httpClient } from '../dataProvider'

const Progress = (props) => {
  const { setLinked, setCheckingLink } = props
  const notify = useNotify()
  const [linkCheckDelay, setLinkCheckDelay] = useState(2000)
  const linkChecks = useRef(30)
  const openedTab = useRef()

  const endChecking = useCallback(
    (success) => {
      setLinkCheckDelay(null)
      setCheckingLink(false)
      if (success) {
        notify('message.lastfmLinkSuccess', 'success')
      } else {
        notify('message.lastfmLinkFailure', 'warning')
      }
      setLinked(success)
    },
    [notify, setCheckingLink, setLinked]
  )

  useEffect(() => {
    openedTab.current = openInNewTab('about:blank')
    httpClient('/api/lastfm/link')
      .then(({ json }) => {
        if (!json.state) throw new Error('Last.fm link state unavailable')
        const callbackEndpoint = baseUrl(
          `/api/lastfm/link/callback?state=${encodeURIComponent(json.state)}`
        )
        const callbackUrl = `${window.location.origin}${callbackEndpoint}`
        openedTab.current.location.href = `https://www.last.fm/api/auth/?api_key=${
          config.lastFMApiKey
        }&cb=${encodeURIComponent(callbackUrl)}`
      })
      .catch(() => {
        openedTab.current?.close()
        endChecking(false)
      })
  }, [endChecking])

  useInterval(() => {
    httpClient('/api/lastfm/link')
      .then((response) => {
        let result = false
        if (response.json.status === true) {
          result = true
          endChecking(true)
        }
        return result
      })
      .then((result) => {
        if (!result && openedTab.current?.closed === true) {
          endChecking(false)
          result = true
        }
        return result
      })
      .then((result) => {
        if (!result && --linkChecks.current === 0) {
          endChecking(false)
        }
      })
      .catch(() => {
        endChecking(false)
      })
  }, linkCheckDelay)

  return <LinearProgress />
}

